"""Formatting property bags.

Every field is optional: ``None`` means "not specified here, inherit".  A
resolved property set is produced by merging, in Word's own order, the document
defaults, the style hierarchy, numbering properties and direct formatting.
"""
from __future__ import annotations

from dataclasses import dataclass, fields, replace
from typing import Optional

from ..oxml import (eighth_points, find, findall, get, half_points, int_of,
                    on_off, twips, val)

BORDER_SIDES = ('top', 'left', 'bottom', 'right', 'insideH', 'insideV', 'between',
                'tl2br', 'tr2bl')


@dataclass(frozen=True)
class Border:
    style: Optional[str] = None
    size: Optional[float] = None     # points
    space: Optional[float] = None    # points
    color: Optional[str] = None      # 'RRGGBB' or None for auto
    theme_color: Optional[str] = None

    @property
    def visible(self) -> bool:
        return bool(self.style) and self.style not in ('none', 'nil') and (self.size or 0) >= 0


@dataclass(frozen=True)
class Shading:
    fill: Optional[str] = None       # 'RRGGBB', None or 'auto'
    color: Optional[str] = None
    pattern: Optional[str] = None
    fill_theme: Optional[str] = None


@dataclass(frozen=True)
class TabStop:
    pos: float = 0.0                 # points from the left text margin
    align: str = 'left'              # left|center|right|decimal|bar|clear
    leader: str = 'none'             # none|dot|hyphen|underscore|heavy|middleDot


def _merge_dataclass(base, over):
    """Fields set on *over* win; ``None`` inherits from *base*."""
    if over is None:
        return base
    if base is None:
        return over
    changes = {}
    for f in fields(base):
        v = getattr(over, f.name)
        if v is None:
            continue
        if f.name == 'borders':
            merged = dict(getattr(base, f.name) or {})
            merged.update(v)
            changes[f.name] = merged
        else:
            changes[f.name] = v
    return replace(base, **changes)


@dataclass(frozen=True)
class RunProps:
    style_id: Optional[str] = None
    font_ascii: Optional[str] = None
    font_hansi: Optional[str] = None
    font_cs: Optional[str] = None
    font_eastasia: Optional[str] = None
    font_hint: Optional[str] = None
    theme_ascii: Optional[str] = None
    theme_hansi: Optional[str] = None
    size: Optional[float] = None          # points
    bold: Optional[bool] = None
    italic: Optional[bool] = None
    underline: Optional[str] = None       # 'single', 'double', 'none', ...
    underline_color: Optional[str] = None
    strike: Optional[bool] = None
    dstrike: Optional[bool] = None
    color: Optional[str] = None           # 'RRGGBB'
    theme_color: Optional[str] = None
    theme_tint: Optional[str] = None
    theme_shade: Optional[str] = None
    highlight: Optional[str] = None       # named colour
    shading: Optional[Shading] = None
    caps: Optional[bool] = None
    small_caps: Optional[bool] = None
    vanish: Optional[bool] = None
    vert_align: Optional[str] = None      # superscript|subscript|baseline
    char_spacing: Optional[float] = None  # points
    position: Optional[float] = None      # points, baseline shift
    scale: Optional[int] = None           # percent
    rtl: Optional[bool] = None
    border: Optional[Border] = None

    def merge(self, other) -> 'RunProps':
        return _merge_dataclass(self, other)


@dataclass(frozen=True)
class ParaProps:
    style_id: Optional[str] = None
    align: Optional[str] = None            # left|center|right|both|distribute
    ind_left: Optional[float] = None       # points
    ind_right: Optional[float] = None
    ind_first_line: Optional[float] = None
    ind_hanging: Optional[float] = None
    space_before: Optional[float] = None
    space_after: Optional[float] = None
    space_before_auto: Optional[bool] = None
    space_after_auto: Optional[bool] = None
    line: Optional[float] = None           # points (or multiple*12 when auto)
    line_rule: Optional[str] = None        # auto|exact|atLeast
    contextual_spacing: Optional[bool] = None
    keep_next: Optional[bool] = None
    keep_lines: Optional[bool] = None
    page_break_before: Optional[bool] = None
    widow_control: Optional[bool] = None
    outline_level: Optional[int] = None
    num_id: Optional[int] = None
    num_level: Optional[int] = None
    borders: Optional[dict] = None
    shading: Optional[Shading] = None
    tabs: Optional[tuple] = None
    bidi: Optional[bool] = None
    suppress_numbering: Optional[bool] = None

    def merge(self, other) -> 'ParaProps':
        merged = _merge_dataclass(self, other)
        if other is not None and other.tabs:
            merged = replace(merged, tabs=merge_tabs(self.tabs, other.tabs))
        return merged


def merge_tabs(base, over):
    stops = {}
    for t in (base or ()):
        stops[round(t.pos, 2)] = t
    for t in (over or ()):
        key = round(t.pos, 2)
        if t.align == 'clear':
            stops.pop(key, None)
        else:
            stops[key] = t
    return tuple(sorted(stops.values(), key=lambda t: t.pos))


@dataclass(frozen=True)
class TableProps:
    style_id: Optional[str] = None
    width: Optional[float] = None
    width_type: Optional[str] = None       # dxa|pct|auto|nil
    align: Optional[str] = None
    indent: Optional[float] = None
    borders: Optional[dict] = None
    shading: Optional[Shading] = None
    cell_margins: Optional[dict] = None    # side -> points
    layout: Optional[str] = None           # fixed|autofit
    cell_spacing: Optional[float] = None
    look: Optional[dict] = None
    row_band_size: Optional[int] = None
    col_band_size: Optional[int] = None

    def merge(self, other) -> 'TableProps':
        return _merge_dataclass(self, other)


@dataclass(frozen=True)
class RowProps:
    height: Optional[float] = None
    height_rule: Optional[str] = None      # auto|atLeast|exact
    cant_split: Optional[bool] = None
    header: Optional[bool] = None
    cell_spacing: Optional[float] = None

    def merge(self, other) -> 'RowProps':
        return _merge_dataclass(self, other)


@dataclass(frozen=True)
class CellProps:
    width: Optional[float] = None
    width_type: Optional[str] = None
    grid_span: Optional[int] = None
    v_merge: Optional[str] = None          # 'restart' | 'continue'
    h_merge: Optional[str] = None
    borders: Optional[dict] = None
    shading: Optional[Shading] = None
    margins: Optional[dict] = None
    v_align: Optional[str] = None          # top|center|bottom
    text_direction: Optional[str] = None
    no_wrap: Optional[bool] = None
    fit_text: Optional[bool] = None

    def merge(self, other) -> 'CellProps':
        return _merge_dataclass(self, other)


# ---------------------------------------------------------------------------
# parsing
# ---------------------------------------------------------------------------

def parse_border(el) -> Optional[Border]:
    if el is None:
        return None
    color = get(el, 'w:color')
    if color in ('auto', None):
        color = None
    return Border(
        style=val(el),
        size=eighth_points(get(el, 'w:sz')),
        space=int_of(get(el, 'w:space')),
        color=color,
        theme_color=get(el, 'w:themeColor'),
    )


def parse_borders(el) -> Optional[dict]:
    if el is None:
        return None
    out = {}
    for side in BORDER_SIDES:
        b = find(el, 'w:' + side)
        if b is not None:
            out[side] = parse_border(b)
    return out or None


def parse_shading(el) -> Optional[Shading]:
    if el is None:
        return None
    fill = get(el, 'w:fill')
    color = get(el, 'w:color')
    return Shading(
        fill=None if fill in (None, 'auto') else fill,
        color=None if color in (None, 'auto') else color,
        pattern=val(el),
        fill_theme=get(el, 'w:themeFill'),
    )


def parse_margins(el) -> Optional[dict]:
    """``w:tblCellMar`` / ``w:tcMar`` -> {'top': pt, ...}."""
    if el is None:
        return None
    out = {}
    for side in ('top', 'left', 'bottom', 'right', 'start', 'end'):
        m = find(el, 'w:' + side)
        if m is None:
            continue
        key = {'start': 'left', 'end': 'right'}.get(side, side)
        w_type = get(m, 'w:type', 'dxa')
        raw = get(m, 'w:w', '0')
        out[key] = twips(raw, 0.0) if w_type != 'nil' else 0.0
    return out or None


def parse_rpr(el, theme=None) -> RunProps:
    """Parse run properties.

    *theme* resolves ``w:asciiTheme`` style references straight away.  That
    matters for the cascade: a run that asks for the theme font must beat an
    explicit family inherited from its style, which it cannot do if the theme
    reference is only resolved later.
    """
    if el is None:
        return RunProps()
    rfonts = find(el, 'w:rFonts')
    color_el = find(el, 'w:color')
    color = val(color_el)
    if color == 'auto':
        color = None
    u = find(el, 'w:u')
    sz = half_points(val(find(el, 'w:sz')))
    spacing = twips(val(find(el, 'w:spacing')))
    position = half_points(val(find(el, 'w:position')))
    ascii_font = get(rfonts, 'w:ascii')
    hansi_font = get(rfonts, 'w:hAnsi')
    eastasia_font = get(rfonts, 'w:eastAsia')
    if theme is not None and rfonts is not None:
        # a theme reference supersedes an explicit family in the same element
        ascii_font = theme.font(get(rfonts, 'w:asciiTheme')) or ascii_font
        hansi_font = theme.font(get(rfonts, 'w:hAnsiTheme')) or hansi_font
        eastasia_font = theme.font(get(rfonts, 'w:eastAsiaTheme')) or eastasia_font
    return RunProps(
        style_id=val(find(el, 'w:rStyle')),
        font_ascii=ascii_font,
        font_hansi=hansi_font,
        font_cs=get(rfonts, 'w:cs'),
        font_eastasia=eastasia_font,
        font_hint=get(rfonts, 'w:hint'),
        theme_ascii=get(rfonts, 'w:asciiTheme'),
        theme_hansi=get(rfonts, 'w:hAnsiTheme'),
        size=sz,
        bold=on_off(find(el, 'w:b')),
        italic=on_off(find(el, 'w:i')),
        underline=val(u) if u is not None else None,
        underline_color=(get(u, 'w:color') if u is not None else None),
        strike=on_off(find(el, 'w:strike')),
        dstrike=on_off(find(el, 'w:dstrike')),
        color=color,
        theme_color=get(color_el, 'w:themeColor'),
        theme_tint=get(color_el, 'w:themeTint'),
        theme_shade=get(color_el, 'w:themeShade'),
        highlight=val(find(el, 'w:highlight')),
        shading=parse_shading(find(el, 'w:shd')),
        caps=on_off(find(el, 'w:caps')),
        small_caps=on_off(find(el, 'w:smallCaps')),
        vanish=on_off(find(el, 'w:vanish')),
        vert_align=val(find(el, 'w:vertAlign')),
        char_spacing=spacing,
        position=position,
        scale=int_of(val(find(el, 'w:w'))),
        rtl=on_off(find(el, 'w:rtl')),
        border=parse_border(find(el, 'w:bdr')),
    )


def parse_tabs(el) -> Optional[tuple]:
    if el is None:
        return None
    stops = []
    for t in findall(el, 'w:tab'):
        pos = twips(get(t, 'w:pos'), 0.0)
        stops.append(TabStop(pos=pos, align=val(t, 'left') or 'left',
                             leader=get(t, 'w:leader', 'none') or 'none'))
    return tuple(sorted(stops, key=lambda t: t.pos)) or None


def parse_ppr(el) -> ParaProps:
    if el is None:
        return ParaProps()
    ind = find(el, 'w:ind')
    spacing = find(el, 'w:spacing')
    num_pr = find(el, 'w:numPr')
    line = None
    line_rule = None
    if spacing is not None:
        line_rule = get(spacing, 'w:lineRule', 'auto')
        raw_line = get(spacing, 'w:line')
        if raw_line is not None:
            if line_rule == 'auto':
                # 240ths of a line
                line = int_of(raw_line, 240) / 240.0
            else:
                line = twips(raw_line)
    first_line = twips(get(ind, 'w:firstLine')) if ind is not None else None
    hanging = twips(get(ind, 'w:hanging')) if ind is not None else None
    left = None
    right = None
    if ind is not None:
        left = twips(get(ind, 'w:left', get(ind, 'w:start')))
        right = twips(get(ind, 'w:right', get(ind, 'w:end')))
    jc = val(find(el, 'w:jc'))
    return ParaProps(
        style_id=val(find(el, 'w:pStyle')),
        align=jc,
        ind_left=left,
        ind_right=right,
        ind_first_line=first_line,
        ind_hanging=hanging,
        space_before=twips(get(spacing, 'w:before')) if spacing is not None else None,
        space_after=twips(get(spacing, 'w:after')) if spacing is not None else None,
        space_before_auto=_autospacing(spacing, 'w:beforeAutospacing'),
        space_after_auto=_autospacing(spacing, 'w:afterAutospacing'),
        line=line,
        line_rule=line_rule,
        contextual_spacing=on_off(find(el, 'w:contextualSpacing')),
        keep_next=on_off(find(el, 'w:keepNext')),
        keep_lines=on_off(find(el, 'w:keepLines')),
        page_break_before=on_off(find(el, 'w:pageBreakBefore')),
        widow_control=on_off(find(el, 'w:widowControl')),
        outline_level=int_of(val(find(el, 'w:outlineLvl'))),
        num_id=int_of(val(find(num_pr, 'w:numId'))) if num_pr is not None else None,
        num_level=int_of(val(find(num_pr, 'w:ilvl'))) if num_pr is not None else None,
        borders=parse_borders(find(el, 'w:pBdr')),
        shading=parse_shading(find(el, 'w:shd')),
        tabs=parse_tabs(find(el, 'w:tabs')),
        bidi=on_off(find(el, 'w:bidi')),
    )


def _autospacing(spacing, name):
    if spacing is None:
        return None
    v = get(spacing, name)
    if v is None:
        return None
    return v not in ('0', 'false', 'off')


def parse_tblpr(el) -> TableProps:
    if el is None:
        return TableProps()
    w = find(el, 'w:tblW')
    ind = find(el, 'w:tblInd')
    look = find(el, 'w:tblLook')
    look_d = None
    if look is not None:
        look_d = {
            'firstRow': _look_flag(look, 'w:firstRow', 0x0020),
            'lastRow': _look_flag(look, 'w:lastRow', 0x0040),
            'firstColumn': _look_flag(look, 'w:firstColumn', 0x0080),
            'lastColumn': _look_flag(look, 'w:lastColumn', 0x0100),
            'noHBand': _look_flag(look, 'w:noHBand', 0x0200),
            'noVBand': _look_flag(look, 'w:noVBand', 0x0400),
        }
    width_type = get(w, 'w:type') if w is not None else None
    width_raw = get(w, 'w:w') if w is not None else None
    width = None
    if width_raw is not None:
        width = twips(width_raw) if width_type != 'pct' else (int_of(width_raw, 0) / 50.0)
    layout_el = find(el, 'w:tblLayout')
    spacing_el = find(el, 'w:tblCellSpacing')
    return TableProps(
        style_id=val(find(el, 'w:tblStyle')),
        width=width,
        width_type=width_type,
        align=val(find(el, 'w:jc')),
        indent=twips(get(ind, 'w:w')) if ind is not None else None,
        borders=parse_borders(find(el, 'w:tblBorders')),
        shading=parse_shading(find(el, 'w:shd')),
        cell_margins=parse_margins(find(el, 'w:tblCellMar')),
        layout=get(layout_el, 'w:type') if layout_el is not None else None,
        cell_spacing=twips(get(spacing_el, 'w:w')) if spacing_el is not None else None,
        look=look_d,
        row_band_size=int_of(val(find(el, 'w:tblStyleRowBandSize'))),
        col_band_size=int_of(val(find(el, 'w:tblStyleColBandSize'))),
    )


def _look_flag(look, attr, bit):
    v = get(look, attr)
    if v is not None:
        return v not in ('0', 'false', 'off')
    raw = val(look)
    if raw:
        try:
            return bool(int(raw, 16) & bit)
        except ValueError:
            return None
    return None


def parse_trpr(el) -> RowProps:
    if el is None:
        return RowProps()
    h = find(el, 'w:trHeight')
    return RowProps(
        height=twips(get(h, 'w:val')) if h is not None else None,
        height_rule=get(h, 'w:hRule') if h is not None else None,
        cant_split=on_off(find(el, 'w:cantSplit')),
        header=on_off(find(el, 'w:tblHeader')),
        cell_spacing=twips(get(find(el, 'w:tblCellSpacing'), 'w:w')) if find(el, 'w:tblCellSpacing') is not None else None,
    )


def parse_tcpr(el) -> CellProps:
    if el is None:
        return CellProps()
    w = find(el, 'w:tcW')
    v_merge = find(el, 'w:vMerge')
    width_type = get(w, 'w:type') if w is not None else None
    width_raw = get(w, 'w:w') if w is not None else None
    width = None
    if width_raw is not None:
        width = twips(width_raw) if width_type != 'pct' else (int_of(width_raw, 0) / 50.0)
    return CellProps(
        width=width,
        width_type=width_type,
        grid_span=int_of(val(find(el, 'w:gridSpan'))),
        v_merge=(val(v_merge, 'continue') or 'continue') if v_merge is not None else None,
        h_merge=(val(find(el, 'w:hMerge'), 'continue')) if find(el, 'w:hMerge') is not None else None,
        borders=parse_borders(find(el, 'w:tcBorders')),
        shading=parse_shading(find(el, 'w:shd')),
        margins=parse_margins(find(el, 'w:tcMar')),
        v_align=val(find(el, 'w:vAlign')),
        text_direction=val(find(el, 'w:textDirection')),
        no_wrap=on_off(find(el, 'w:noWrap')),
    )
